    const K = D.K;
    baseC = document.createElement('canvas');
    baseC.width = canvas.width; baseC.height = canvas.height;
    const c = baseC.getContext('2d', { willReadFrequently: true });
    c.setTransform(K, 0, 0, K, -DR.x * K, -DR.y * K);
    const path = new Path2D(CFG.full);
