          // when a grain lifts off: away from the cursor + a soft, coherent breeze, slightly upward
          const ax = px - ccx, ay = py - ccy, ad = Math.hypot(ax, ay) || 1;
          const f = -1.5708 + 1.2 * Math.sin(hx[i] * 0.009 / K + hy[i] * 0.021 / K + D.seed)
                            + 0.9 * Math.sin(hy[i] * 0.029 / K - hx[i] * 0.006 / K + D.seed * 1.7);
          let vx = 0.85 * ax / ad + Math.cos(f), vy = 0.85 * ay / ad + Math.sin(f) - 0.2;
          const vn = Math.hypot(vx, vy) || 1, m = (16 + 92 * Math.pow(mg[i], 1.5)) * K;
          ox[i] = vx / vn * m; oy[i] = vy / vn * m;
